function debounce(fn: Function, ms: number): Function {
    let timer: ReturnType<typeof setTimeout> | null = null;

    return function (this: any, ...args: any[]) {
        if (timer !== null) {
            clearTimeout(timer);
        }
        timer = setTimeout(() => {
            fn.apply(this, args);
            timer = null;
        }, ms);
    };
}
